+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { spawnSync } = require('node:child_process');
+const { resolve } = require('node:path');
+
+const command = resolve(__dirname, '../bin/slug.js');
+const run = (...args) => spawnSync(process.execPath, [command, ...args], { encoding: 'utf8' });
+
+test('turns words and punctuation into a slug', () => {
+  const result = run('Hello World!');
+  assert.equal(result.status, 0);
+  assert.equal(result.stdout, 'hello-world\n');
+  assert.equal(result.stderr, '');
+});
+
+test('replaces accents with plain letters', () => {
+  const result = run('Café');
+  assert.equal(result.status, 0);
+  assert.equal(result.stdout, 'cafe\n');
+});
+
+test('keeps non-Latin letters and numbers', () => {
+  const result = run('東京 2026');
+  assert.equal(result.status, 0);
+  assert.equal(result.stdout, '東京-2026\n');
+});
+
+test('rejects a title without letters or numbers', () => {
+  const result = run('!!!');
+  assert.equal(result.status, 1);
+  assert.equal(result.stdout, '');
+  assert.match(result.stderr, /letter or number/);
+});

